export function paintCaption(ctx,canvas,text,s,time=0,cue={}){const w=canvas.width,h=canvas.height,fs=Math.round(Math.min(w,h)*s.size/100),lh=fs*1.18;ctx.save();ctx.font=`700 ${fs}px "${s.font}"`;const tokens=cue.words?.length?cue.words.map(w=>({...w,text:w.text||w.word})):String(text).split(/\s+/).filter(Boolean).map(text=>({text}));let lines=[],line=[],width=0;const space=ctx.measureText(' ').width;for(const token of tokens){const tw=ctx.measureText(token.text).width;if(line.length&&width+space+tw>w*.82){lines.push(line);line=[];width=0}line.push({...token,width:tw});width+=(line.length>1?space:0)+tw}if(line.length)lines.push(line);let page=0;if(lines.length>2){if(cue.words?.length){const index=lines.findIndex(row=>row.some(t=>time>=t.start&&time<t.end));page=Math.max(0,Math.floor((index<0?lines.length-1:index)/2))}else{const progress=Math.max(0,Math.min(.999,(time-(cue.start||0))/Math.max(.01,(cue.end||1)-(cue.start||0))));page=Math.floor(progress*Math.ceil(lines.length/2))}}lines=lines.slice(page*2,page*2+2);const bh=lines.length*lh,margin=h*s.safe/100;let y=s.position==='top'?margin:s.position==='center'?(h-bh)/2:h-margin-bh;ctx.textAlign='left';ctx.textBaseline='top';const rowWidth=row=>Math.min(w*.88,row.reduce((n,t)=>n+t.width,0)+space*Math.max(0,row.length-1));if(s.style==='plate'||s.style==='karaoke'){const tw=Math.max(...lines.map(rowWidth),0)+fs*.8;ctx.fillStyle=s.style==='karaoke'?'rgba(0,0,0,.38)':'rgba(0,0,0,.74)';ctx.beginPath();ctx.roundRect((w-tw)/2,y-fs*.25,tw,bh+fs*.45,fs*.2);ctx.fill()}let active=null;if(s.style==='karaoke')for(const t of tokens)if(t.start<=time)active=t;for(const row of lines){let x=(w-rowWidth(row))/2;for(const t of row){ctx.strokeStyle='rgba(0,0,0,.92)';ctx.lineWidth=fs*.11;ctx.lineJoin='round';ctx.shadowColor='#000';ctx.shadowBlur=fs*.13;if(['outline','karaoke'].includes(s.style))ctx.strokeText(t.text,x,y,w*.84);ctx.fillStyle=s.style==='karaoke'&&active&&t.start===active.start?(s.highlight||'#f4d740'):(s.color||'#fff');ctx.fillText(t.text,x,y,w*.84);x+=t.width+space}y+=lh}ctx.restore()}
